using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Media.UpdateMediaMetadata;public sealed class UpdateMediaMetadataCommandHandler(IMediaReferenceRepository repo,IContentAuditService audit,IUnitOfWork uow):ICommandHandler<UpdateMediaMetadataCommand,Result>{public async Task<Result> HandleAsync(UpdateMediaMetadataCommand c,CancellationToken ct=default){var x=await repo.GetByIdAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.MediaNotFound);var before=ContentAuditSnapshots.From(x);x.UpdateMetadata(c.AltText,c.Caption,c.MetadataJson,c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.MediaUpdated,ContentAuditActions.Updated,ContentAuditEntityTypes.MediaReference,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);return Result.Success();}}
